-- Seed: 93 verified creator prospects, discovered 2026-07-25.
--
-- PREREQUISITE: migration 060_creator_prospects.sql must already be applied.
-- This file applies NO migration and creates NO schema.
--
-- It creates no creator_profiles, no auth users, no billing rows, no pages
-- and no claim codes. Every row lands at stage 'identified' for review.
--
-- ON CONFLICT DO NOTHING makes this safe to run twice and safe to run after
-- a partial CSV import: the unique indexes on lower(email) and
-- (platform, lower(platform_handle)) skip anything already present.
-- Nothing existing is updated or deleted.

begin;

on conflict do nothing;

-- Verify: expect 93 loaded, all at stage 'identified', 23 with an email,
-- 0 with a follower count (blank by design - none were verifiable).
select count(*) as prospects_loaded,
       count(*) filter (where stage = 'identified') as at_identified,
       count(*) filter (where email is not null) as with_email,
       count(*) filter (where follower_count is not null) as with_follower_count
from public.creator_prospects;

commit;
